// Generated by Suite Builder from a crawl of the site. The suite's guide: in your browser, or here in the terminal (node menu/guide.mjs [page]).
// EDIT RULES: do not edit this file; regenerating replaces all of it. The menu is menu/menu.mjs; your own commands go in a file of your own.
// The suite's guide: its pages in guide/, read in the browser (one page, every section, a list of them beside it)
// or here, in the terminal, the same words as plain text. A computer with no screen (Linux with no display, an SSH
// session, a pipeline) gets the terminal. Typed: node menu/guide.mjs [page] [--browser | --terminal];
// help <page> in this folder prints a page too.
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const DIR = join(ROOT, 'guide');
const WIDTH = Math.min(100, Math.max(60, (process.stdout.columns ?? 100) - 2)); // not a heuristic: a page's measure, as a book sets one

/** The guide's pages, in order: guide/01-this-suite.md is "this-suite". */
function pages() {
  if (!existsSync(DIR)) return [];
  return readdirSync(DIR)
    .filter((f) => /^\d\d-[a-z-]+\.md$/.test(f))
    .sort()
    .map((f) => {
      const md = readFileSync(join(DIR, f), 'utf8').replace(/^<!--[^\n]*-->\n/, '');
      return { topic: f.slice(3, -3), title: /^# (.*)$/m.exec(md)?.[1] ?? f, md };
    });
}

const cells = (line) =>
  line
    .trim()
    .replace(/^\||\|$/g, '')
    .split('|')
    .map((c) => c.trim());

/** A page's blocks: headings, paragraphs, lists, tables, code. */
function blocks(md) {
  const out = [];
  const lines = md.split('\n');
  for (let i = 0; i < lines.length; ) {
    const line = lines[i];
    if (!line.trim()) {
      i++;
      continue;
    }
    if (line.startsWith('```')) {
      const code = [];
      for (i++; i < lines.length && !lines[i].startsWith('```'); i++) code.push(lines[i]);
      out.push({ kind: 'code', lines: code });
      i++;
      continue;
    }
    const heading = /^(#{1,3}) (.*)$/.exec(line);
    if (heading) {
      out.push({ kind: 'heading', level: heading[1].length, text: heading[2] });
      i++;
      continue;
    }
    if (line.startsWith('|')) {
      const rows = [];
      for (; i < lines.length && lines[i].startsWith('|'); i++) if (!/^\|\s*-/.test(lines[i])) rows.push(cells(lines[i]));
      out.push({ kind: 'table', rows });
      continue;
    }
    if (/^(- |\d+\. )/.test(line)) {
      const ordered = /^\d/.test(line);
      const items = [];
      for (; i < lines.length && (/^(- |\d+\. )/.test(lines[i]) || (/^ {2,}\S/.test(lines[i]) && items.length)); i++) {
        if (/^(- |\d+\. )/.test(lines[i])) items.push(lines[i].replace(/^(- |\d+\. )/, ''));
        else items[items.length - 1] += ` ${lines[i].trim()}`;
      }
      out.push({ kind: 'list', ordered, items });
      continue;
    }
    const para = [];
    for (; i < lines.length && lines[i].trim() && !/^(#|\||```|- |\d+\. )/.test(lines[i]); i++) para.push(lines[i].trim());
    out.push({ kind: 'paragraph', text: para.join(' ') });
  }
  return out;
}

function wrap(text, width, indent = '') {
  const lines = [];
  let line = '';
  for (const word of text.split(' ')) {
    if (line && line.length + 1 + word.length > width) {
      lines.push(line);
      line = indent + word;
    } else line = line ? `${line} ${word}` : word;
  }
  if (line) lines.push(line);
  return lines.join('\n');
}

const plain = (t) => t.replace(/`([^`]*)`/g, '$1').replace(/\*\*([^*]*)\*\*/g, '$1');

/** A page as plain text, for the terminal. */
function asText(md) {
  return blocks(md)
    .map((b) => {
      if (b.kind === 'heading')
        return `${b.level === 1 ? plain(b.text).toUpperCase() : plain(b.text)}\n${(b.level === 1 ? '=' : '-').repeat(Math.min(WIDTH, b.text.length))}`;
      if (b.kind === 'paragraph') return wrap(plain(b.text), WIDTH);
      if (b.kind === 'code') return b.lines.map((l) => `    ${l}`).join('\n');
      if (b.kind === 'list')
        return b.items.map((it, n) => wrap(`${b.ordered ? `${n + 1}.` : '-'} ${plain(it)}`, WIDTH, '  ')).join('\n');
      // A table: each row's first cell, then the rest under it.
      return b.rows
        .slice(1)
        .map((r) => `${wrap(`- ${plain(r[0])}`, WIDTH, '  ')}\n${r.slice(1).map((c) => `    ${wrap(plain(c), WIDTH - 4, '    ')}`).join('\n')}`)
        .join('\n');
    })
    .join('\n\n');
}

const html = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = (t) => html(t).replace(/`([^`]*)`/g, '<code>$1</code>').replace(/\*\*([^*]*)\*\*/g, '<strong>$1</strong>');

/** A page as HTML, its sections given ids for the list beside it. */
function asHtml(md, prefix) {
  const sections = [];
  const body = blocks(md)
    .map((b) => {
      if (b.kind === 'heading') {
        const id = b.level === 1 ? prefix : `${prefix}-${b.text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`;
        if (b.level === 2) sections.push({ id, title: b.text });
        return `<h${b.level + 1} id="${id}">${inline(b.text)}</h${b.level + 1}>`;
      }
      if (b.kind === 'paragraph') return `<p>${inline(b.text)}</p>`;
      if (b.kind === 'code') return `<pre><code>${html(b.lines.join('\n'))}</code></pre>`;
      if (b.kind === 'list')
        return `<${b.ordered ? 'ol' : 'ul'}>${b.items.map((it) => `<li>${inline(it)}</li>`).join('')}</${b.ordered ? 'ol' : 'ul'}>`;
      const [head, ...rows] = b.rows;
      return `<table><thead><tr>${head.map((c) => `<th>${inline(c)}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${inline(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
    })
    .join('\n');
  return { body, sections };
}

/** The whole guide as one page. */
function guideHtml(all) {
  const parts = all.map((p) => ({ p, ...asHtml(p.md, p.topic) }));
  const nav = parts
    .map(({ p, sections }) => `<li><a href="#${p.topic}">${html(p.title)}</a><ul>${sections.map((s) => `<li><a href="#${s.id}">${html(s.title)}</a></li>`).join('')}</ul></li>`)
    .join('');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>The suite's guide</title>
<style>:root{--bg:#fff;--fg:#1d1d1f;--dim:#5f6368;--line:#dadce0;--code:#f1f3f4;--link:#1a56db}
@media (prefers-color-scheme:dark){:root{--bg:#121212;--fg:#e8eaed;--dim:#9aa0a6;--line:#3c4043;--code:#1e1e1e;--link:#8ab4f8}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.55 system-ui,-apple-system,Segoe UI,sans-serif;display:flex}
nav{position:sticky;top:0;height:100vh;overflow:auto;width:280px;flex:none;padding:24px 16px;border-right:1px solid var(--line);font-size:14px}
nav ul{list-style:none;margin:0;padding:0}nav ul ul{padding-left:12px;margin:2px 0 8px}nav li{margin:3px 0}nav ul ul a{color:var(--dim)}
main{max-width:860px;padding:24px 32px 120px;flex:1;min-width:0}a{color:var(--link);text-decoration:none}a:hover{text-decoration:underline}
section{border-bottom:1px solid var(--line);padding-bottom:24px;margin-bottom:24px}h2{font-size:26px;margin-top:8px}h3{font-size:18px;margin-top:28px}
code{background:var(--code);padding:1px 5px;border-radius:4px;font-size:13px}pre{background:var(--code);padding:12px 14px;border-radius:6px;overflow:auto}pre code{padding:0;background:none}
table{border-collapse:collapse;width:100%;margin:12px 0}th,td{border:1px solid var(--line);padding:6px 9px;text-align:left;vertical-align:top}th{color:var(--dim);font-weight:600}
@media (max-width:760px){body{display:block}nav{position:static;height:auto;width:auto;border-right:0;border-bottom:1px solid var(--line)}main{padding:16px}}</style></head>
<body><nav><strong>The suite's guide</strong><ul>${nav}</ul></nav><main>
${parts.map(({ body }) => `<section>${body}</section>`).join('\n')}
</main></body></html>
`;
}

/** A computer with a screen, a person at it: Windows and Mac, Linux with a display; never a pipeline or a piped output. */
function hasScreen() {
  if (!process.stdout.isTTY || process.env.CI || process.env.SUITE_NO_OPEN) return false;
  if (process.platform === 'win32' || process.platform === 'darwin') return true;
  return Boolean(process.env.DISPLAY || process.env.WAYLAND_DISPLAY);
}

function list(all) {
  const width = Math.max(...all.map((p) => p.topic.length));
  return all.map((p) => `  help ${p.topic.padEnd(width)}  ${p.title}`).join('\n');
}

const args = process.argv.slice(2);
const all = pages();
if (!all.length) {
  console.log('This suite has no guide/ folder: it was built before the guide. A rebuild by Suite Builder writes it.');
  process.exit(1);
}
const asked = args.find((a) => !a.startsWith('-'));
if (asked) {
  const word = asked.toLowerCase().replace(/^the-/, '');
  // A word a person reaches for: help bugs, help ci.
  const also = { bugs: 'the-sites-defects', audit: 'the-sites-defects', issues: 'the-sites-defects', ci: 'pipelines-and-sharing', pipeline: 'pipelines-and-sharing', pack: 'pipelines-and-sharing', yours: 'your-changes', rebuild: 'your-changes', run: 'running', failed: 'a-failure', troubleshooting: 'when-something-goes-wrong' };
  const page = all.find((p) => p.topic === word || p.topic.replace(/^the-/, '') === word || also[word] === p.topic || p.topic.split('-').includes(word));
  if (!page) {
    console.log(`No page "${asked}" in the guide. Its pages:\n${list(all)}`);
    process.exit(1);
  }
  if (!args.includes('--browser')) {
    console.log(asText(page.md));
    process.exit(0);
  }
}
const dir = join(tmpdir(), `suite-guide-${ROOT.replace(/[^A-Za-z0-9]+/g, '-').slice(-60)}`);
mkdirSync(dir, { recursive: true });
const file = join(dir, 'index.html');
writeFileSync(file, guideHtml(all));
if (!args.includes('--terminal') && hasScreen()) {
  const viewer = process.platform === 'win32' ? ['explorer', file] : process.platform === 'darwin' ? ['open', file] : ['xdg-open', file];
  const run = spawnSync(viewer[0], viewer.slice(1), { stdio: 'ignore' });
  // Windows' explorer opens a page in the default browser (and answers 1 even then).
  if (!run.error && (process.platform === 'win32' || !run.status)) {
    console.log(`Opened the guide in your browser: ${file}\nHere, one page at a time: help <page>, e.g. help running.`);
    process.exit(0);
  }
}
console.log(`The guide, one page at a time, here:\n\n${list(all)}\n\nFor a browser, the whole guide is in ${file}: copy it to a computer with a screen.`);
